export function getLocationBySlug(slug: string): SacredLocation | undefined {
  return sacredLocations.find((loc) => loc.slug === slug)
}

export function getPadavs(): SacredLocation[] {
  return sacredLocations.filter((loc) => loc.type === 'padav').sort((a, b) => (a.dayNumber || 0) - (b.dayNumber || 0))
}

export function getShrines(): SacredLocation[] {
  return sacredLocations.filter((loc) => loc.type !== 'padav')
}
